use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl < 'ast > Visit < 'ast > for MacroVisitor { fn visit_item_macro (& mut self , i : & 'ast ItemMacro) { self . macros . push (MacroInfo { name : i . mac . path . segments . last () . map_or ("" . to_string () , | s | s . ident . to_string ()) , kind : "macro_rules" . to_string () , file : self . file_path . display () . to_string () , line : i . mac . span () . start () . line , column : i . mac . span () . start () . column , signature : Some (quote :: quote ! { # i } . to_string ()) , doc_comment : get_doc_comment (& i . attrs) , }) ; syn :: visit :: visit_item_macro (self , i) ; } fn visit_item_fn (& mut self , i : & 'ast ItemFn) { let mut is_proc_macro = false ; let mut macro_kind = String :: new () ; for attr in & i . attrs { if attr . path () . is_ident ("proc_macro") { is_proc_macro = true ; macro_kind = "proc_macro" . to_string () ; break ; } else if attr . path () . is_ident ("proc_macro_attribute") { is_proc_macro = true ; macro_kind = "proc_macro_attribute" . to_string () ; break ; } else if attr . path () . is_ident ("proc_macro_derive") { is_proc_macro = true ; macro_kind = "proc_macro_derive" . to_string () ; break ; } } if is_proc_macro { self . macros . push (MacroInfo { name : i . sig . ident . to_string () , kind : macro_kind , file : self . file_path . display () . to_string () , line : i . span () . start () . line , column : i . span () . start () . column , signature : Some (quote :: quote ! { # i . sig } . to_string ()) , doc_comment : get_doc_comment (& i . attrs) , }) ; } syn :: visit :: visit_item_fn (self , i) ; } }
}